class Counter {
    int count = 0;
    void add(int n) { count += n; }
    void addAll(int[] nums) {
        for (int n : nums) add(n); // calls add() internally
    }
}

class LoggingCounter extends Counter {
    int addCount = 0;
    @Override
    void add(int n) { addCount++; super.add(n); } // counts each add call
}

// Problem: addAll calls add() internally, so addCount gets incremented N times
// If parent changes addAll to not use add(), subclass behavior silently breaks
LoggingCounter lc = new LoggingCounter();
lc.addAll(new int[]{1, 2, 3}); // addCount == 3 (unexpected if parent changes)

interface Coffee { String getDescription(); double getCost(); }

class SimpleCoffee implements Coffee {
    public String getDescription() { return "Coffee"; }
    public double getCost() { return 1.0; }
}

// Decorator uses composition — holds a Coffee reference, adds milk behavior
class MilkDecorator implements Coffee {
    private final Coffee coffee; // composition!
    MilkDecorator(Coffee c) { this.coffee = c; }
    public String getDescription() { return coffee.getDescription() + ", Milk"; }
    public double getCost() { return coffee.getCost() + 0.25; }
}

// Combine at runtime without new subclasses
Coffee order = new MilkDecorator(new SimpleCoffee()); // Coffee + Milk
